// NodeDeploymentState maps exactly to the documented NodeDeployment states.
// UNSPECIFIED is a wire sentinel and is never a valid persisted domain state.
type NodeDeploymentState int32

const (
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_UNSPECIFIED     NodeDeploymentState = 0
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_QUEUED          NodeDeploymentState = 1
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_DELIVERED       NodeDeploymentState = 2
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_STAGED          NodeDeploymentState = 3
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_PRECHECKED      NodeDeploymentState = 4
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_ACTIVATED       NodeDeploymentState = 5
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_HEALTHY         NodeDeploymentState = 6
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_FAILED          NodeDeploymentState = 7
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_REVERTING       NodeDeploymentState = 8
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_REVERTED        NodeDeploymentState = 9
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_ROLLBACK_FAILED NodeDeploymentState = 10
	// The following states are reported only on MULTI_TENANT_RUNTIME sessions.
	// The Agent applies one scope at a time under a node-level lock. After
	// DELIVERED (sequence 1) it reports AGENT_QUEUED (2) while waiting behind
	// other scopes and STARTED (3) when it takes the lock; later transitions
	// continue from 4. The control plane's apply deadline starts at STARTED.
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_AGENT_QUEUED NodeDeploymentState = 11
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_STARTED      NodeDeploymentState = 12
	// SUPERSEDED is terminal and follows AGENT_QUEUED: a newer deployment for the
	// same scope replaced this one before it started; the running configuration
	// is unchanged. A full local queue (16 entries) is reported as FAILED after
	// AGENT_QUEUED with a retryable RATE_LIMITED ProtocolError.
	NodeDeploymentState_NODE_DEPLOYMENT_STATE_SUPERSEDED NodeDeploymentState = 13
)

